  'not-enough-para3' => 'बहुत बड़े दस्तावेज़ों के लिए एक अन्य विकल्प यह है कि भेजने से पहले उन्हें छोटे-छोटे खंडों में विभाजित कर दिया जाए। पीडीएफटूल्स पर पीडीएफ स्प्लिटर आपको विशिष्ट पेज निकालने की सुविधा देता है, जिससे आप पूरे दस्तावेज़ के बजाय प्रत्येक प्राप्तकर्ता को केवल प्रासंगिक अनुभाग भेज सकते हैं।',
  'common-problems-heading' => 'सामान्य संपीड़न समस्याएँ और उन्हें कैसे ठीक करें',
  'problem1-heading' => 'संपीड़न के बाद भी फ़ाइल बहुत बड़ी है',
  'problem1-text' => 'यदि 50 एमबी फ़ाइल को केवल 45 एमबी तक संपीड़ित किया जाता है, तो अंदर की छवियां पहले से ही जेपीईजी जैसे संपीड़ित प्रारूप में होने की संभावना है। पीडीएफ संपीड़न उपकरण दृश्य गुणवत्ता हानि के बिना पहले से ही संपीड़ित डेटा को नहीं हटा सकता है। अधिकतम संपीड़न सेटिंग का उपयोग करने का प्रयास करें, या विचार करें कि क्या दस्तावेज़ को छोटे भागों में विभाजित करना किसी एकल फ़ाइल को अत्यधिक संपीड़ित करने से अधिक व्यावहारिक है।',
  'problem2-heading' => 'संपीड़न के बाद पाठ धुंधला दिखता है',
  'problem2-text' => 'ऐसा तब होता है जब कंप्रेसर टेक्स्ट क्षेत्रों को छवियों के रूप में गलत पहचानता है और उन पर छवि संपीड़न लागू करता है। ऐसे टूल का उपयोग करें जो टेक्स्ट और छवि संपीड़न को अलग करता है, या संपीड़न शक्ति को कम करता है। अधिकांश दस्तावेज़ों के लिए इस समस्या से बचने के लिए PDFTools में अनुशंसित सेटिंग को कैलिब्रेट किया गया है।',
  'problem3-heading' => 'संपीड़ित फ़ाइल मूल से बड़ी है',
  'problem3-text' => 'ऐसा कभी-कभी होता है जब एक पीडीएफ पहले से ही अच्छी तरह से अनुकूलित होता है। इसे दोबारा संपीड़ित करने से सामग्री को हटाए बिना संरचनात्मक ओवरहेड जुड़ जाता है। पहले से संपीड़ित फ़ाइल को दोबारा संपीड़ित करने के बजाय अपने मूल स्रोत दस्तावेज़ से नए सिरे से शुरुआत करें।',
  'conclusion-heading' => 'निष्कर्ष',
  'conclusion-para1' => 'गुणवत्ता खोए बिना पीडीएफ फ़ाइल का आकार कम करना सबसे व्यावहारिक दस्तावेज़ कौशल में से एक है जिसे आप विकसित कर सकते हैं। अधिकांश बड़े आकार के पीडीएफ में उच्च-रिज़ॉल्यूशन वाली छवियां होती हैं जिन्हें स्क्रीन पर किसी भी दृश्य परिवर्तन के बिना दोबारा नमूना लिया जा सकता है, और एक निःशुल्क टूल का उपयोग करके इस प्रक्रिया में दो मिनट से कम समय लगता है।',
  'conclusion-para2' => 'बिना किसी सॉफ़्टवेयर इंस्टालेशन के त्वरित परिणामों के लिए PDFTools पर कंप्रेशन टूल से शुरुआत करें। अधिक जटिल स्थितियों के लिए, इस गाइड के सिद्धांत आपको यह समझने में मदद करेंगे कि एक विशेष पीडीएफ बड़ा क्यों है और कौन सा दृष्टिकोण इसे सबसे प्रभावी ढंग से कम करेगा। समय के साथ गुणवत्ता हानि से बचने के लिए मुख्य आदत हमेशा पहले से संपीड़ित संस्करण के बजाय मूल स्रोत फ़ाइल से संपीड़ित करना है।',
  'conclusion-para3' => 'संबंधित कार्यों के लिए, ईमेल द्वारा बड़ी पीडीएफ फाइलें भेजने के लिए गाइड और बड़े दस्तावेज़ों को प्रबंधनीय अनुभागों में तोड़ने के लिए पीडीएफ स्प्लिटर टूल देखें।',
  'faqs-heading' => 'अक्सर पूछे जाने वाले प्रश्नों',
  'faq1-question' => 'गुणवत्ता खोए बिना मैं पीडीएफ फाइल का आकार कितना कम कर सकता हूं?',
  'faq1-answer' => 'छवि-भारी पीडीएफ के लिए, दोषरहित संपीड़न गुणवत्ता में कोई बदलाव किए बिना 20 से 40 प्रतिशत की कमी प्राप्त करता है। मध्यम सेटिंग्स पर हानिपूर्ण संपीड़न आमतौर पर गुणवत्ता के साथ 60 से 75 प्रतिशत की कमी प्राप्त करता है जो स्क्रीन पर अप्रभेद्य है। एक 10 एमबी पीडीएफ को मानक मॉनिटर पर बिना किसी दृश्य अंतर के आमतौर पर 2 से 3 एमबी तक लाया जा सकता है।',
  'faq2-question' => 'क्या ऑनलाइन टूल का उपयोग करके पीडीएफ को कंप्रेस करना सुरक्षित है?',
  'faq2-answer' => 'हाँ, किसी प्रतिष्ठित सेवा का उपयोग करते समय। PDFTools एन्क्रिप्टेड फ़ाइल स्थानांतरण का उपयोग करता है और एक घंटे के बाद सभी अपलोड की गई फ़ाइलों को स्वचालित रूप से हटा देता है। फ़ाइलें तीसरे पक्ष के साथ साझा नहीं की जाती हैं या अनुरोधित ऑपरेशन से परे किसी भी उद्देश्य के लिए उपयोग नहीं की जाती हैं। उन दस्तावेज़ों के लिए जिनमें अत्यधिक गोपनीय जानकारी होती है, डेस्कटॉप सॉफ़्टवेयर जो फ़ाइलों को पूरी तरह से स्थानीय रखता है, विचार करने लायक एक विकल्प है।',
  'faq3-question' => 'क्या पीडीएफ को कंप्रेस करने से उसकी खोज योग्यता प्रभावित होती है?',
  'faq3-answer' => 'नहीं, पीडीएफ में पाठ को छवि डेटा से अलग संग्रहीत किया जाता है और छवि संपीड़न द्वारा छुआ नहीं जाता है। संपीड़न के बाद, आप अभी भी दस्तावेज़ को खोज सकते हैं, पाठ की प्रतिलिपि बना सकते हैं, और फ़ाइल को खोज इंजन द्वारा अनुक्रमित कर सकते हैं। संपीड़न से केवल छवि गुणवत्ता प्रभावित होती है।',
  'faq4-question' => 'क्या मैं एक पीडीएफ को कई बार कंप्रेस कर सकता हूँ?',
  'faq4-answer' => 'हां, लेकिन घटते रिटर्न और बढ़ते गुणवत्ता जोखिम के साथ। छवि डेटा पर प्रत्येक अतिरिक्त संपीड़न पास और अधिक गिरावट का कारण बनता है। हमेशा मूल असम्पीडित स्रोत दस्तावेज़ से काम करें, और एक ही संपीड़न पास में अपने लक्ष्य फ़ाइल आकार तक पहुंचने का लक्ष्य रखें।',
  'faq5-question' => 'अधिकतम सुरक्षित ईमेल अनुलग्नक आकार क्या है?',
  'faq5-answer' => 'जीमेल और अधिकांश प्रमुख ईमेल प्रदाता 25 एमबी तक के अटैचमेंट स्वीकार करते हैं। कई कॉर्पोरेट ईमेल सिस्टम की सीमा न्यूनतम 10 एमबी है। सभी प्राप्तकर्ताओं के बीच अधिकतम अनुकूलता के लिए, पीडीएफ अनुलग्नकों को 10 एमबी से कम रखना एक सुरक्षित लक्ष्य है।',
);
